using HfDrive.Desktop.Services;
using HfDrive.Desktop.ViewModels;
using Microsoft.UI.Xaml;

namespace HfDrive.Desktop;

/// <summary>
/// WinUI application entry point (the entry point itself is generated by the
/// WinUI XAML compiler for WinExe projects). Owns the single provider session
/// and root view model for the window; the session is disposed when the window
/// closes. The application never fabricates account or sync state.
/// </summary>
public partial class App : Application
{
    private Window? _window;
    private TrayService? _tray;

    public App()
    {
        InitializeComponent();
        ViewModel = new MainViewModel(Session);
    }

    /// <summary>The one provider session shared by all views of this window.</summary>
    public ProviderSession Session { get; } = new();

    /// <summary>The root view model shared by all views of this window.</summary>
    public MainViewModel ViewModel { get; }

    /// <summary>
    /// The one application window, exposed so native pickers and other
    /// ownership surfaces can use its handle (native folder picker ownership).
    /// </summary>
    public Window? DesktopWindow => _window;

    protected override void OnLaunched(LaunchActivatedEventArgs args)
    {
        ViewModel.ApplySessionState();
        _window = new MainWindow(ViewModel);
        _window.Closed += (_, _) =>
        {
            // The UI never owns provider lifetime; it only releases its own IPC
            // connection when the window closes.
            _tray?.Dispose();
            ViewModel.Dispose();
            _ = Session.DisposeAsync().AsTask();
        };
        _window.Title = "HF Drive";
        _window.Activate();
        _tray = new TrayService(_window);
    }
}
